from pathlib import Path
import csv, zipfile, shutil, re
from docx import Document
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill
from pptx import Presentation
ROOT=Path('.'); BASE=ROOT/'Production-Quality-Review.html'
DISCLAIMER=Path('DISCLAIMER.txt').read_text()
def make_doc(p,title,sections):
 d=Document(); d.add_heading(title,0); d.add_paragraph('Synthetic Knowledge Pack | Industrial AI Workbench')
 for h,t in sections: d.add_heading(h,1); d.add_paragraph(t)
 d.add_paragraph('All organizations, people, metrics, dates, and events are fictional and synthetic.')
 d.save(p)
def make_xlsx(p,rows):
 w=Workbook(); ws=w.active; ws.title='Analysis'
 for r in rows: ws.append(r)
 for c in ws[1]: c.font=Font(bold=True,color='FFFFFF'); c.fill=PatternFill('solid',fgColor='5B2C6F')
 ws.freeze_panes='A2'; ws.auto_filter.ref=ws.dimensions; w.save(p)
def make_pptx(p,title,slides):
 r=Presentation(); r.core_properties.title=title
 for i,(h,b) in enumerate(slides):
  s=r.slides.add_slide(r.slide_layouts[0 if i==0 else 1]); s.shapes.title.text=h; s.placeholders[1].text=b
 r.save(p)
def eml(p,date,frm,subject,body): p.write_text(f'Date: {date} 09:15:00 +0200\nFrom: {frm}\nTo: procurement-team@example.invalid\nSubject: {subject}\n\n{body}\n')
def ics(p,date,subject): p.write_text(f'BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//Industrial AI Workbench//Synthetic\nBEGIN:VEVENT\nDTSTART:{date.replace("-","")}T090000\nDTEND:{date.replace("-","")}T100000\nSUMMARY:{subject}\nDESCRIPTION:Synthetic demo meeting.\nEND:VEVENT\nEND:VCALENDAR\n')
def pack(d,slug,items,cfg):
 out=d/'knowledge'/slug; shutil.rmtree(out,ignore_errors=True); (out/'downloads').mkdir(parents=True); rows=[]
 def add(name,typ,stakeholder,role,fn,date='2026-10-01'):
  fn(out/name); items.append(name); rows.append([name,date,typ,stakeholder,role])
 for x in cfg['docs']: add(x[0],'business document',x[1],x[2],lambda p,x=x:make_doc(p,x[3],x[4]))
 for x in cfg['emails']: add(x[0],'email',x[2],x[3],lambda p,x=x:eml(p,x[1],x[2],x[4],x[5]),x[1])
 for x in cfg['meetings']: add(x[0],'calendar invite',x[2],x[3],lambda p,x=x:ics(p,x[1],x[4]),x[1])
 for x in cfg['notes']: add(x[0],x[1],x[2],x[3],lambda p,x=x:make_doc(p,x[4],x[5]),x[6])
 for x in cfg['workbooks']: add(x[0],'analysis workbook',x[1],x[3],lambda p,x=x:make_xlsx(p,x[2]))
 for x in cfg['presentations']: add(x[0],'presentation',x[1],x[3],lambda p,x=x:make_pptx(p,x[2],x[4]))
 for x in cfg.get('signals',[]): add(x[0],'synthetic public-signal excerpt',x[1],x[3],lambda p,x=x:p.write_text(x[4]),x[2])
 readme=cfg['readme']+'\n\n'+DISCLAIMER; (out/'README.txt').write_text(readme); rows.insert(0,['README.txt','2026-10-01','readme','Synthetic demo team','Safe demo disclaimer'])
 with (out/'source-manifest.csv').open('w',newline='') as f: w=csv.writer(f); w.writerow(['file','date','source_type','stakeholder','storyline_role']); w.writerows(rows)
 groups={'documents':[],'emails':[],'meetings':[],'analysis':[],'complete':items+['README.txt','source-manifest.csv']}
 for n in items:
  k='emails' if n.endswith('.eml') else 'meetings' if n.endswith('.ics') or 'transcript' in n or 'notes' in n else 'analysis' if n.endswith(('.xlsx','.pptx')) else 'documents'; groups[k].append(n)
 for k,fs in groups.items():
  with zipfile.ZipFile(out/'downloads'/f'knowledge-pack-{k}.zip','w',zipfile.ZIP_DEFLATED) as z:
   for n in fs: z.write(out/n,n)
 html=BASE.read_text(); c=cfg
 rep={'Production Quality Review':c['title'],'production-quality-review':slug,'Find out what is driving a quality issue.':c['hero'],'Use a connected Knowledge Pack to understand a rising component fault and recommend what the team should do next.':c['intro'],'Synthetic demo data · 45–60 minutes · Industrial operations':c['meta'],'This scenario combines many sources, several reasoning steps, and a final leadership presentation.':c['cowork'],'How a quality signal became a decision':c['storytitle'],'53 scenario items':f"{c['count']} scenario items",'Connect the story, make a recommendation, and present the decision.':c['task'],'Bring together the documents, messages, meetings, notes, and data. Cowork will turn the investigation into a leadership presentation and action tracker.':c['tasktext'],'8 business documents':f"{c['docs']} business documents",'30 individual .eml files':f"{c['emails']} individual .eml files",'Use the complete Knowledge Pack to investigate the production quality issue. Work through the evidence systematically: build a dated timeline, analyze the quality and production trends, compare stakeholder perspectives, identify contradictions and missing information, assess the business impact, and recommend the next action. Then create a polished PowerPoint presentation for plant leadership with the issue overview, evidence, timeline, trend visuals, stakeholder perspectives, decision options, recommended action, open questions, and next steps. Also create a corrective-action tracker. Distinguish confirmed facts from assumptions and cite the source filenames used.':c['prompt'],'A clear issue summary and dated timeline':c['outcomes'][0],'Comparison of stakeholder perspectives':c['outcomes'][1],'Evidence-based recommendation':c['outcomes'][2],'Leadership presentation with evidence and visuals':c['outcomes'][3],'Corrective-action tracker with owners and next steps':c['outcomes'][4]}
 for a,b in rep.items(): html=html.replace(a,b)
 html=re.sub(r'<div class="story-copy">.*?</div>','<div class="story-copy">'+''.join(f'<p>{p}</p>' for p in c['story'])+'</div>',html,flags=re.S)
 html=re.sub(r'<div class="source-count">8</div><span class="source-label">Documents</span>',f'<div class="source-count">{c["docs"]}</div><span class="source-label">Documents</span>',html)
 html=re.sub(r'<div class="source-count">30</div><span class="source-label">Email messages</span>',f'<div class="source-count">{c["emails"]}</div><span class="source-label">Email messages</span>',html)
 html=re.sub(r'<div class="source-count">10</div><span class="source-label">Meetings</span>',f'<div class="source-count">{c["meetings"]}</div><span class="source-label">Meetings</span>',html)
 html=re.sub(r'<div class="source-count">3</div><span class="source-label">Workbooks</span>',f'<div class="source-count">{c["workbooks"]}</div><span class="source-label">Workbooks</span>',html)
 html=re.sub(r'<div class="source-count">2</div><span class="source-label">Presentations</span>',f'<div class="source-count">{c["presentations"]}</div><span class="source-label">Presentations</span>',html)
 html=html.replace('knowledge/production-quality-review/',f'knowledge/{slug}/').replace('Production Quality Review</strong>',c['title']+'</strong>')
 html=html.replace('For direct attachment, download and extract the ZIP before attaching individual files.',c['loading'])
 html=html.replace('Review the files I provided. List the documents, email conversations, meetings, transcripts, notes, and workbooks you can access. Do not analyze the issue yet. Identify any sources that appear unavailable or incomplete.',c['check'])
 for n in ['documents','emails','meetings','analysis']:
  html=html.replace('53 scenario items · ZIP archive',f'{c["count"]} scenario items · ZIP archive').replace('Workbooks and presentations',f'{c["workbooks"]} workbooks and {c["presentations"]} presentation')
 (ROOT/c['page']).write_text(html)

def cfg(title,slug,page,hero,counts,context,story,task,prompt,outcomes,readme,docs,emails,meetings,notes,workbooks,presentations,signals=[]):
 return dict(title=title,slug=slug,page=page,hero=hero,intro=hero+' Review the connected Knowledge Pack and turn dispersed evidence into a defensible decision.',meta='Synthetic demo data · 45–60 minutes · Industrial procurement',cowork='This scenario combines many sources, several reasoning steps, and a final leadership-ready decision artifact.',storytitle='How the evidence became a decision',count=sum(counts),docs=counts[0],emails=counts[1],meetings=counts[2],workbooks=counts[3],presentations=counts[4],task=task,tasktext='Bring together the connected documents, messages, meetings, notes, and data. Cowork should produce a traceable recommendation and leadership-ready artifact.',prompt=prompt,check='Review the files I provided. List the documents, email conversations, meetings, transcripts, notes, and workbooks you can access. Do not analyze the issue yet. Identify any sources that appear unavailable or incomplete.',loading='For direct attachment, download and extract the ZIP before attaching individual files. For OneDrive or SharePoint, extract the complete pack and upload the folders.',outcomes=outcomes,readme=readme,story=story,docs_data=docs,emails_data=emails,meetings_data=meetings,notes=notes,workbooks_data=workbooks,presentations_data=presentations,signals_data=signals)
people='Avery Ortiz; Jordan Lee; Samira Khan; Mateo Ruiz; Chen Wei'
def quick_docs(names): return [(n,'Procurement team','Decision support / evidence',n.replace('.docx','').replace('-',' ').title(),[('Evidence','This synthetic source connects the storyline with dated metrics, assumptions, and a decision-relevant contradiction.'),('Action','Use this source with the workbooks and communications; cite the filename in the final output.')]) for n in names]
def quick_emails(names,subjects): return [(n,date,'Nadia Petrov','Chronology and decision trail',s,'Synthetic email: '+s+'. The team should cite this filename and distinguish the stated fact from assumptions.') for n,date,s in zip(names,['2026-04-07','2026-04-14','2026-04-16','2026-04-20','2026-04-24','2026-04-27','2026-10-02','2026-10-07'],subjects)]
def quick_meet(names,dates,subjects): return [(n,s,d,'Meeting evidence',sub) for n,d,sub in zip(names,dates,subjects) for s in [people]]
def notes(names): return [(n,'meeting transcript','Nadia Petrov','Meeting evidence',n.replace('.docx','').replace('-',' ').title(),[('Discussion','Stakeholders compare evidence, identify a contradiction, and agree that the recommendation must show uncertainty.'),('Decision','Assign an owner and date for each unresolved condition.')],date) for n,date in zip(names,['2026-04-20','2026-04-24'])]

rfq=cfg('RFQ Comparison Award','rfq-comparison-award','RFQ-Comparison-Award.html','Compare three quotations and make the award decision.',(5,8,5,2,1),[],['On 7 April, a fictional team issues RFQ-HA240 for 2,400 hydraulic actuators. Aster Dynamics, Boreal Motion, and Cinder Industrial reply in different currencies and commercial structures.','The comparison is not decision-ready: currencies, Incoterms, freight, tooling, payment terms, and lead-time commitments are inconsistent. Cinder contradicts itself between its cover letter and schedule appendix.','Procurement, engineering, finance, and operations normalize the evidence. Boreal scores highest while Aster remains a qualified contingency.','The executive review must approve a defensible recommendation and conditions, not simply select the lowest visible unit price.'],'Normalize the quotes, recommend an award, and write the executive note.','Normalize the three supplier quotations. Reconcile currencies, Incoterms, freight, tooling, terms, lead times, technical fit, and FX assumptions. Score suppliers, identify contradictions, recommend a primary award plus contingency, and create an executive award note and presentation with source filename citations.',['Normalized supplier comparison with assumptions','Evidence-backed award recommendation and contingency','Executive award note with conditions','Timeline, contradictions, and source citations','Decision-ready presentation and follow-up actions'],'This fictional RFQ scenario uses three invented suppliers and quotations dated April 2026. Recommended outcome: Boreal Motion primary with Aster Dynamics as contingency.',quick_docs(['document-01-component-requirements.docx','document-02-rfq-clarifications.docx','document-03-normalized-quote-comparison.docx','document-04-draft-award-note.docx','document-05-sourcing-brief.docx']),quick_emails(['email-01-rfq-issued.eml','email-02-aster-quote.eml','email-03-boreal-quote.eml','email-04-cinder-quote.eml','email-05-finance-fx-assumption.eml','email-06-engineering-fit-review.eml','email-07-evaluation-panel.eml','email-08-award-approval-request.eml'],['RFQ issued for HA-240','Aster quotation: USD 198 FCA','Boreal quotation: EUR 203 DDP','Cinder quotation: GBP 171 CIF','FX and landed-cost assumptions','Engineering fit review','Evaluation panel outcome','Approval requested: HA-240 award']),quick_meet(['calendar-01-rfq-normalization.ics','calendar-02-evaluation-panel.ics','calendar-03-award-review.ics'],['2026-04-20','2026-04-24','2026-04-27'],['RFQ normalization workshop','Supplier evaluation panel','Executive award review']),notes(['transcript-01-rfq-normalization.docx','notes-01-evaluation-panel.docx']),[('workbook-01-rfq-evaluation.xlsx','Finance',[['Supplier','Quote','Currency','Term','Lead weeks','Normalized EUR','Score'],['Aster Dynamics',198,'USD','FCA',10,'=198*2400/1.09+24000',81],['Boreal Motion',203,'EUR','DDP',9,'=203*2400',88],['Cinder Industrial',171,'GBP','CIF',12,'=171*2400*0.86+18000/0.86+12000',74]],'Analysis workbook'),('workbook-02-rfq-sensitivity.xlsx','Finance',[['Scenario','Boreal EUR','Aster EUR','Cinder EUR'],['Base',487200,460000,506000],['FX sensitivity',487200,483000,506000]],'Analysis workbook')],[('presentation-01-executive-award-note.pptx','Nadia Petrov','Executive award note',[('Award request','Approve Boreal Motion for HA-240'),('Normalization','Currency, Incoterms, freight, tooling, terms, lead time'),('Recommendation','Boreal primary; Aster contingency')])])
sp=cfg('Supplier Performance Review','supplier-performance-review','Supplier-Performance-Review.html','Turn supplier performance signals into an executive review pack.',(6,10,6,3,1),[],['The fictional supplier council reviews Atlas Forge, Meridian Seals, and Redwood Controls across Q2 and Q3 2026. The headline scorecard improves in some places but conceals meaningful operational and commercial issues.','Atlas delivery rises from 89% to 96%, yet quality remains at 1,320 PPM and operations records 1,180 expedite hours. Meridian is on time but adds a 4.8% surcharge without index evidence.','Redwood is strategically important for resilience, but its capacity claim differs between the supplier email and internal spreadsheet.','The 8 October executive review needs monitored improvement, commercial challenge, and funded resilience qualification.'],'Assess supplier performance, explain the gaps, and recommend differentiated actions.','Reconcile delivery, quality, cost, expedite, and resilience evidence across scorecards, emails, meetings, reports, and the prior presentation. Identify contradictions, recommend differentiated actions for Atlas Forge, Meridian Seals, and Redwood Controls, and create an executive review pack with citations.',['Supplier-by-supplier performance narrative','Reconciled scorecard and business impact','Differentiated action plan with owners and dates','Contradictions, risks, and escalation thresholds','Executive review presentation'],'This fictional pack covers invented suppliers and synthetic operating data from July through October 2026.',quick_docs(['document-01-scorecard-method.docx','document-02-quarterly-review-brief.docx','document-03-corrective-action-plan.docx','document-04-business-impact-report.docx','document-05-draft-review-pack.docx','document-06-review-agenda.docx']),quick_emails(['email-01-scorecards-released.eml','email-02-atlas-recovery.eml','email-03-atlas-quality-escalation.eml','email-04-meridian-surcharge.eml','email-05-cost-variance.eml','email-06-redwood-capacity.eml','email-07-q3-scorecards.eml','email-08-expedite-impact.eml','email-09-supplier-council.eml','email-10-executive-pre-read.eml'],['Q2 scorecards released','Atlas recovery plan','Atlas quality escalation','Meridian surcharge notice','Cost variance review','Redwood capacity signal','Q3 scorecards released','Expedite impact','Supplier council recommendation','Executive pre-read']),quick_meet(['calendar-01-quality-escalation.ics','calendar-02-cost-review.ics','calendar-03-resilience-workshop.ics','calendar-04-executive-review.ics'],['2026-07-18','2026-08-14','2026-09-22','2026-10-08'],['Atlas quality escalation','Meridian cost review','Redwood resilience workshop','Executive supplier review']),notes(['transcript-01-executive-review.docx','notes-01-resilience-workshop.docx']),[('workbook-01-supplier-scorecard.xlsx','Nadia Petrov',[['Supplier','OTD Q2','OTD Q3','Quality PPM','Cost variance','Score'],['Atlas Forge',89,96,1320,2.1,72],['Meridian Seals',97,98,540,4.8,78],['Redwood Controls',94,93,680,1.7,76]],'Scorecard'),('workbook-02-expedite-cost.xlsx','Leo Martins',[['Supplier','Expedite hours','Cost EUR'],['Atlas Forge',1180,31600],['Meridian Seals',0,42600],['Redwood Controls',240,8400]],'Impact'),('workbook-03-action-tracker.xlsx','Priya Shah',[['Action','Owner','Due','Status'],['Atlas containment','Atlas Forge','2026-10-20','Open'],['Meridian index evidence','Meridian','2026-10-15','Open'],['Redwood capacity validation','Nadia','2026-10-22','Open']],'Actions')],[('presentation-01-prior-supplier-review.pptx','Nadia Petrov','Prior supplier review',[('Q2 review','Atlas delivery weakness'),('Q3 update','Delivery recovered; quality and expedite burden remain'),('Executive asks','Approve three differentiated actions')])])
risk=cfg('Supply Base Risk Scan','supply-base-risk-scan','Supply-Base-Risk-Scan.html','Rank supplier risks from internal exposure and synthetic public-signal excerpts.',(8,8,5,2,1),[],['On 1 September, a fictional procurement team refreshes its supplier register and discovers concentrated exposure in a few critical relationships. Internal exposure data is combined with clearly labelled synthetic public-signal excerpts.','Helio Semiconductors has 18% of electronics spend and no qualified alternate. Kestrel Freight depends on a concentrated lane with a hypothetical 21-day recovery signal. Northwind Castings has a nine-day buffer against a 14-week lead time.','Stakeholders disagree about whether to treat excerpts as evidence or prompts for validation. Legal insists that the pack clearly state that public-signal excerpts are synthetic and not live research.','The executive readout ranks risks, distinguishes internal facts from synthetic signals, and assigns 30/60/90-day mitigation actions.'],'Scan the supply base, rank risk, and propose practical mitigations.','Use the internal register, exposure workbooks, stakeholder communications, meetings, and clearly labelled synthetic public-signal excerpts. Rank risks using the stated scoring method, distinguish verified internal facts from scenario signals, explain uncertainty, and create an executive readout with 30/60/90-day mitigations. State prominently that public-signal excerpts are synthetic and not live research.',['Ranked risk register with scoring rationale','Exposure and single-source analysis','Synthetic-signal caveat and uncertainty log','30/60/90-day mitigation plan','Executive risk readout with citations'],'This fictional pack uses an invented supplier register and clearly labelled synthetic public-signal excerpts. Public-signal excerpts are synthetic and not live research.',quick_docs(['document-01-supplier-register.docx','document-02-risk-methodology.docx','document-03-ranked-risk-register.docx','document-04-mitigation-options.docx','document-05-stakeholder-brief.docx','document-06-public-signal-handling.docx','document-07-30-60-90-plan.docx','document-08-executive-readout-brief.docx']),quick_emails(['email-01-register-refresh.eml','email-02-finance-exposure.eml','email-03-logistics-signal.eml','email-04-operations-concern.eml','email-05-legal-caveat.eml','email-06-risk-scoring-review.eml','email-07-mitigation-options.eml','email-08-executive-pre-read.eml'],['Supplier register refresh','Spend concentration review','Lane disruption signal','Operations concern','Caveat for public signals','Scoring review','Mitigation options','Risk scan pre-read']),quick_meet(['calendar-01-risk-workshop.ics','calendar-02-scoring-review.ics','calendar-03-executive-readout.ics'],['2026-09-19','2026-09-29','2026-10-08'],['Supply-base risk workshop','Risk scoring review','Executive risk readout']),notes(['transcript-01-risk-workshop.docx','notes-01-scoring-review.docx']),[('workbook-01-supplier-risk-scoring.xlsx','Nadia Petrov',[['Supplier','Impact','Confidence','Horizon','Mitigation difficulty','Risk score','Band'],['Helio Semiconductors',90,75,80,85,'=B2*0.4+C2*0.2+D2*0.2+E2*0.2','Red'],['Kestrel Freight',80,70,85,70,'=B3*0.4+C3*0.2+D3*0.2+E3*0.2','Red'],['Northwind Castings',85,60,75,65,'=B4*0.4+C4*0.2+D4*0.2+E4*0.2','Amber']], 'Scoring'),('workbook-02-exposure-register.xlsx','Leo Martins',[['Supplier','Category','Annual spend EUR','Single source','Alternate qualified','Buffer days'],['Helio Semiconductors','Electronics',4200000,'Yes','No',18],['Kestrel Freight','Logistics',1800000,'No','Partial',21],['Northwind Castings','Castings',2600000,'Yes','No',9]],'Exposure')],[('presentation-01-executive-risk-readout.pptx','Nadia Petrov','Executive risk readout',[('Top ranked risks','Helio, Kestrel, Northwind'),('What is known','Internal register and exposure data'),('What is not known','Synthetic excerpts require validation'),('30/60/90-day actions','Qualify alternates, test lanes, refresh signals')])],[('signal-01-helio-financial-excerpt.txt','Synthetic signal archive','2026-09-12','Financial signal','SYNTHETIC PUBLIC-SIGNAL EXCERPT — NOT LIVE RESEARCH\nHelio Semiconductors: fictional analyst-style excerpt describing a hypothetical liquidity-watch pattern. No real company, source, filing, or market data is referenced.'),('signal-02-kestrel-logistics-excerpt.txt','Synthetic signal archive','2026-09-14','Operational/logistics signal','SYNTHETIC PUBLIC-SIGNAL EXCERPT — NOT LIVE RESEARCH\nKestrel Freight: fictional lane bulletin describing a hypothetical port-congestion event and 21-day recovery estimate. This is not a live logistics update.'),('signal-03-northwind-geopolitical-excerpt.txt','Synthetic signal archive','2026-09-16','Geopolitical/logistics signal','SYNTHETIC PUBLIC-SIGNAL EXCERPT — NOT LIVE RESEARCH\nNorthwind Castings: fictional scenario note describing a hypothetical export-control review in a made-up region. It is not a real geopolitical assessment.')])
for c in [rfq,sp,risk]:
 pack(ROOT,c['slug'],[],dict(docs=c['docs_data'],emails=c['emails_data'],meetings=c['meetings_data'],notes=c['notes'],workbooks=c['workbooks_data'],presentations=c['presentations_data'],signals=c['signals_data'],readme=c['readme']))
